# rectangle detection: find border-colored rectangles and fill interior
import numpy as np
def boxes(g):
    g=np.array(g); H,W=g.shape
    bg=Counter(g.flatten().tolist()).most_common(1)[0][0]
    seen=np.zeros_like(g,bool); res=[]
    for r in range(H):
        for c in range(W):
            if g[r,c]!=bg and not seen[r,c]:
                col=g[r,c]
                # bounding box of connected same-color via flood
                stack=[(r,c)]; comp=[]
                seen[r,c]=1
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and g[ny,nx]==col:
                            seen[ny,nx]=1; stack.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                res.append((min(ys),min(xs),max(ys),max(xs),col,len(comp)))
    return res
